          if (lower.startsWith('.تجاهل')) { let nums = getTargets(text, ctx, quotedParticipant); let expanded = await expandTargets(nums, from); for (let n of expanded) { delete pendingBotConfirm[n]; if (whiteList.indexOf(n) === -1) whiteList.push(n); } saveLists(); await r('✅ تجاهلته'); continue; }
          if (lower === '.فخ') { if (!isGroup) { await r('⚠️ في القروب بس'); continue; } let trapText = '.فحص_وهمي_' + Math.floor(Math.random()*9999); trapActive[from] = { time: Date.now(), trapText }; await sock.sendMessage(from, { text: trapText }); await r('🪤 فخ: ' + trapText); continue; }
          if (lower === '.كشف') { let nums = getTargets(text, ctx, quotedParticipant); let expanded = await expandTargets(nums, from); if (!expanded.length) { await r('⚠️ رد عليه واكتب .كشف'); continue; } await r('🔍 كشف ' + expanded[0] + ':\nبوت: ' + (knownBots.includes(expanded[0]) ? 'ايه ✅' : 'لا ❌')); continue; }
          if (lower === '.فحص عميق') { if (!isGroup) { await r('⚠️ في القروب بس'); continue; } try { let meta = await sock.groupMetadata(from); let kicked = []; for (let p of meta.participants) { let nn = getParticipantNum(p); if (isMe(p) || isWhiteParticipant(p) || isOwner(nn)) continue; if (p.admin) continue; let d = await deepCheckUser(p, from); if (d.isBot) { let ok = await kickAndRename(from, p.id, 'فحص عميق'); if (ok) kicked.push(nn); } } saveLists(); await r('🔍 فحص عميق: طردت ' + kicked.length); } catch(e) { await r('خطأ: ' + e.message); } continue; }
          if (lower === '.قائمة بوتات' || lower === '.بوتات') { await r('🤖 بوتات:\n' + (knownBots.length ? knownBots.join('\n') : 'فاضية')); continue; }
