          if (lower.includes('.بوت حذف')) { let nums = getTargets(text, ctx, quotedParticipant); let expanded = await expandTargets(nums, from); for (let n of expanded) knownBots = knownBots.filter(x => x !== n); saveLists(); await r('✅ نحيت'); continue; }
          if (lower === '.داتا') { try { if (!isGroup) { await r('⚠️ في القروب بس'); continue; } let meta = await sock.groupMetadata(from); let target = null; if (quotedParticipant) target = meta.participants.find(x => getNum(x.id) === getNum(quotedParticipant)); if (!target) { await r('⚠️ رد عليه واكتب .داتا'); continue; } await r('DATA:\n' + JSON.stringify(target, null, 2).slice(0, 3000)); try { let biz = await sock.getBusinessProfile(target.id); await r('BIZ:\n' + JSON.stringify(biz, null, 2).slice(0, 2000)); } catch(e) { await r('BIZ ERROR'); } let rev = await revealPhone(target, ctx, quotedParticipant); await r('📱 الرقم: ' + (rev.hidden ? 'مخفي' : rev.phone)); } catch(e) { await r('خطأ: ' + e.message); } continue; }
